PATCH
export PATH="$JAVA_HOME/bin:$PATH"
ant -quiet test.compile && java -cp 'build/lombok-transplants:build/lombok-utils:build/lombok-utils6:build/lombok-main:build/lombok-main8:build/tests:build/teststubs:lib/test/*:lib/stripe/*' org.junit.runner.JUnitCore FieldDefaultsRegression

cd /testbed && patch -p1 <<'PATCH'
--- /dev/null
+++ b/build/field-defaults-compile/Foo.java
@@ -0,0 +1,22 @@
+public record Foo() {
+	record NestedRecord(String value) {
+	}
+	static class NestedClass {
+		int value = 1;
+	}
+}
+
+record WithComponents(String value) {
+}
+
+class Ordinary {
+	int value = 1;
+}
+
+enum Enumeration {
+	ONE;
+	int value = 1;
+}
+
+interface Contract { int VALUE = 1; }
--- /dev/null
+++ b/build/field-defaults-compile/InvalidRecord.java
@@ -0,0 +1,3 @@
+@lombok.experimental.FieldDefaults(makeFinal = true)
+record InvalidRecord(String value) {
+}
PATCH
export PATH="$JAVA_HOME/bin:$PATH"
for private in false true; do
  for final in false true; do
    printf 'config.stopBubbling = true\nlombok.fieldDefaults.defaultPrivate = %s\nlombok.fieldDefaults.defaultFinal = %s\n' "$private" "$final" > build/field-defaults-compile/lombok.config
    javac -cp dist/lombok.jar -d build/field-defaults-compile/classes build/field-defaults-compile/Foo.java || exit 1
    modifiers=$(javap -p build/field-defaults-compile/classes/Ordinary.class | grep 'int value;')
    expected='  '
    if [ "$private" = true ]; then expected="${expected}private "; fi
    if [ "$final" = true ]; then expected="${expected}final "; fi
    expected="${expected}int value;"
    if [ "$modifiers" != "$expected" ]; then printf 'Incorrect modifiers: %s\n' "$modifiers"; exit 1; fi
    if javac -cp dist/lombok.jar -d build/field-defaults-compile/classes build/field-defaults-compile/InvalidRecord.java > build/field-defaults-compile/invalid.log 2>&1; then
      echo 'Explicit @FieldDefaults incorrectly accepted on a record'; exit 1
    fi
    grep -q '@FieldDefaults is only supported on a class or an enum.' build/field-defaults-compile/invalid.log || exit 1
    printf 'PASS direct javac: defaultPrivate=%s, defaultFinal=%s; explicit annotation still rejected\n' "$private" "$final"
  done
done

